+interface Option {
+  name: string;
+  alias: string;
+  default?: string;
+  description: string;
+}
+
+interface ParsedArgs {
+  [key: string]: string | boolean;
+}
+
+export function parseArgs(args: string[], options: Option[]): ParsedArgs {
+  const result: ParsedArgs = {};
+  const optionMap = new Map(
+    options.map(opt => [opt.name, opt])
+  );
+
+  for (let i = 0; i < args.length; i++) {
+    const arg = args[i];
+    if (arg.startsWith('--')) {
+      const name = arg.slice(2);
+      const option = optionMap.get(name);
+      if (option) {
+        const next = args[i + 1];
+        result[name] = next && !next.startsWith('-') ? next : true;
+        if (next && !next.startsWith('-')) i++;
+      }
+    } else if (arg.startsWith('-')) {
+      const alias = arg.slice(1);
+      const option = options.find(o => o.alias === alias);
+      if (option) {
+        const next = args[i + 1];
+        result[option.name] = next && !next.startsWith('-') ? next : true;
+        if (next && !next.startsWith('-')) i++;
+      }
+    }
+  }
+
+  for (const opt of options) {
+    if (!(opt.name in result) && opt.default !== undefined) {
+      result[opt.name] = opt.default;
+    }
+  }
+
+  return result;
+}
+
+export function printHelp(options: Option[]): void {
+  console.log('用法: parse-args [选项]');
+  for (const opt of options) {
+    console.log(`  -${opt.alias}, --${opt.name}   ${opt.description}`);
+  }
+}
